#include <functional>
#include <memory>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    constexpr bool acceptsAllocator =
        std::uses_allocator<std::function<int(int)>, std::allocator<int>>::value;
    // The C++11/C++14 specification provided this specialization, but implementations
    // differed. C++17 removed allocator support from std::function.
    (void)acceptsAllocator;
    std::function<int(int)> function = [](int n) { return n + 1; };
    assert(function(2) == 3);
}
